{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Azure SQL Database zone redundancy disabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database explicitly disables zone redundancy, leaving it more susceptible to service disruption from a single availability-zone failure. The S2 tier does not support zone redundancy, so a zone-capable tier is also required."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"P1\"\n  zone_redundant = true\n}\n",
  "fix_summary": "Enabled zone redundancy and changed the database from S2 to the zone-redundancy-capable P1 tier."
}
